def dif_Square(n: int) -> bool:
    # A number n can be represented as a difference of two squares if and only if:
    # n = a^2 - b^2 = (a-b)(a+b)
    #
    # Since (a-b) and (a+b) are integers, their product is n.
    # Also, (a+b) and (a-b) must have the same parity (both even or both odd).
    #
    # Equivalently:
    # - If n is odd, then n can always be represented as difference of two squares.
    # - If n is divisible by 4, then n can be represented as difference of two squares.
    # - If n is even but not divisible by 4, then it cannot be represented.
    #
    # This characterization holds for all integers n.

    if n % 2 != 0:
        return True
    return n % 4 == 0


