def next_smallest_palindrome(num: int) -> int:
    def is_all_nines(n: str) -> bool:
        return all(ch == '9' for ch in n)

    s = str(num)
    length = len(s)

    # If all 9's, the next palindrome is 10...01 (length+1)
    if is_all_nines(s):
        return int('1' + ('0' * (length - 1)) + '1')

    # Helper to build palindrome by mirroring left to right
    def make_palindrome(left: str, odd_length: bool) -> str:
        if odd_length:
            return left + left[:-1][::-1]
        else:
            return left + left[::-1]

    odd = (length % 2 != 0)
    half_len = (length + 1) // 2  # length of the left half including middle if odd

    left_half = s[:half_len]
    palindrome = make_palindrome(left_half, odd)

    if int(palindrome) > num:
        return int(palindrome)

    # Increment the left half and mirror again
    # Convert left half to int, add 1
    left_num = int(left_half) + 1
    left_half_str = str(left_num)

    # If incrementing left_half increases length, it means the palindrome length increases by 1
    if len(left_half_str) > half_len:
        # For example 999 +1 = 1000, length increased
        # The next palindrome is 10...01 with length+1
        return int('1' + ('0' * (length - 1)) + '1')

    palindrome = make_palindrome(left_half_str, odd)
    return int(palindrome)


