def find_solution(a, b, n):
    def extended_gcd(aa, bb):
        if bb == 0:
            return aa, 1, 0
        d, x1, y1 = extended_gcd(bb, aa % bb)
        x = y1
        y = x1 - (aa // bb) * y1
        return d, x, y

    d, x0, y0 = extended_gcd(a, b)
    if n % d != 0:
        return "No solution"

    # Scale the initial solution
    x0 *= n // d
    y0 *= n // d

    # Coefficients for generating all solutions
    kx = b // d
    ky = a // d

    # We want non-negative x and y
    # General solution: x = x0 + k*kx, y = y0 - k*ky
    # Find k so that x >= 0 and y >= 0:
    # x0 + k*kx >= 0  => k >= -x0 / kx
    # y0 - k*ky >= 0  => k <= y0 / ky

    from math import ceil, floor

    k_min = ceil(-x0 / kx) if kx != 0 else float('-inf')
    k_max = floor(y0 / ky) if ky != 0 else float('inf')

    if k_min > k_max:
        return "No solution"

    # Choose any k in [k_min, k_max], pick k = k_min for the smallest non-negative x
    k = k_min

    x = x0 + k * kx
    y = y0 - k * ky

    if x < 0 or y < 0:
        return "No solution"

    return ('x = ', x, ', y = ', y)


