def get_total_number_of_sequences(n: int, max_element: int) -> int:
    # dp[i][x]: number of sequences of length i ending with element x
    # Elements are integers from 1 to max_element
    if n == 1:
        return max_element  # sequences of length 1: any element from 1 to max_element

    dp = [0] * (max_element + 1)
    for x in range(1, max_element + 1):
        dp[x] = 1  # sequences of length 1 ending with x

    for length in range(2, n + 1):
        new_dp = [0] * (max_element + 1)
        # To efficiently calculate, for each x, sum dp[y] for all y <= x//2
        # Precompute prefix sums of dp to do this quickly
        prefix = [0] * (max_element + 1)
        for i in range(1, max_element + 1):
            prefix[i] = prefix[i - 1] + dp[i]

        for x in range(1, max_element + 1):
            limit = x // 2
            if limit >= 1:
                new_dp[x] = prefix[limit]
            else:
                new_dp[x] = 0
        dp = new_dp

    return sum(dp[1:])  # sum sequences of length n ending with any element


