def find_Max(nums):
    left, right = 0, len(nums) - 1
    # If array is not rotated (last element > first element), max is last element
    if nums[left] < nums[right]:
        return nums[right]

    while left < right:
        mid = (left + right) // 2
        # If mid element is greater than the rightmost element, max is in the right half including mid
        if nums[mid] > nums[right]:
            left = mid + 1
        else:
            right = mid
    # After the loop, left points to the minimum element, max is element before it
    return nums[left - 1]


