def filter_data(data, min_height=None, min_width=None):
    """
    Filters a dictionary of students mapping names to (height, width) tuples,
    returning a new dictionary with only students whose height >= min_height
    and width >= min_width (if these are provided).

    Parameters:
    - data: dict[str, tuple(height, width)]
    - min_height: minimum height allowed (inclusive), or None for no lower bound
    - min_width: minimum width allowed (inclusive), or None for no lower bound

    Returns:
    - dict with filtered students
    """
    return {
        name: (h, w)
        for name, (h, w) in data.items()
        if (min_height is None or h >= min_height) and (min_width is None or w >= min_width)
    }


