def lucky_num(n):
    # Generate lucky numbers using the classical sieve method

    # Start with the list of odd numbers (since 1 is lucky)
    numbers = list(range(1, 2 * n * 10, 2))  # initial oversize list to ensure enough lucky numbers

    idx = 1  # start at second element (index 1), since first is 1 and stays
    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th number from the list, starting counting at index 0
        # But note: the step-th number means remove every element at position multiples of step (1-based)
        # We need to remove elements at indices: step-1, 2*step-1, 3*step-1, ...
        # But since indices are zero-based, the first removal is at index step-1, then step-1 + step, etc.
        # Actually, the classical sieve is implemented by removing elements at indices that are multiples of step, starting from step-1

        # To remove every step-th element, we create a new list excluding those
        numbers = [num for i, num in enumerate(numbers) if (i + 1) % step != 0]

        idx += 1
        if len(numbers) >= n:
            # If we have enough lucky numbers, we can stop early
            # But continue sieve until idx < len(numbers) to keep correctness (optional)
            pass

    return numbers[:n]


