def dif_Square(n: int) -> bool:
    # n = a^2 - b^2 = (a-b)(a+b)
    # Let x = a-b, y = a+b; then n = x*y
    # a = (x+y)/2, b = (y-x)/2 must be integers => x and y have same parity
    # So n can be represented as difference of squares if n has a factorization n = x*y
    # where x and y have the same parity.
    # For n=0, 0 = 0^2 - 0^2 so True.

    if n == 0:
        return True

    abs_n = abs(n)
    # Check all factor pairs (x,y) with x*y = n
    # where x and y have same parity
    # since a,b integers require (x+y) and (y-x) even => x,y same parity
    for x in range(1, int(abs_n**0.5) + 1):
        if abs_n % x == 0:
            y = abs_n // x
            # Check for positive factor pairs and negative factor pairs because n can be negative
            # Check pair (x,y)
            if (x % 2) == (y % 2):
                # Now assign signs to x,y to get n:
                # Since n = x*y or n = (-x)*(-y), check if x*y == n or (-x)*(-y) == n
                if x * y == n or (-x) * (-y) == n:
                    return True
            # Also check pair (y,x) since order matters for parity check
            if (y % 2) == (x % 2):
                if y * x == n or (-y) * (-x) == n:
                    return True
    return False


