def next_smallest_palindrome(num: int) -> int:
    if num <= 0:
        # No positive palindrome smaller than 0
        return -1

    def is_palindrome(x: int) -> bool:
        s = str(x)
        return s == s[::-1]

    # Start from num-1 and go down until we find a palindrome
    for candidate in range(num - 1, -1, -1):
        if is_palindrome(candidate):
            return candidate
    return -1  # if no palindrome found (should not happen for positive num)


