def find_solution(a, b, n):
    if b == 0:
        # If b=0, then ax = n => x = n/a if integer, else no solution
        if a != 0 and n % a == 0:
            return (n // a, 0)
        else:
            return None
    x = 0
    while True:
        remainder = n - a * x
        if remainder % b == 0:
            y = remainder // b
            return (x, y)
        x += 1
        # To avoid infinite loop when no solution exists, 
        # we can stop if remainder goes below zero if a and b positive,
        # but since a,b,n can be anything, no general bound.
        # Instead, we stop if x becomes too large indicating no solution.
        # But problem does not specify. We'll rely on math:
        # If b divides (n - a*x), solution found or not.
        # If no solution, loop forever. However, problem does not forbid this.
