def find_Max(nums):
    if not nums:
        return None  # or raise an error if empty input is invalid

    left, right = 0, len(nums) - 1

    # If the list is not rotated (sorted ascending), the last element is the max
    if nums[left] < nums[right]:
        return nums[right]

    while left < right:
        mid = (left + right) // 2
        # If mid element is greater than the rightmost element, max must be at mid or to the right
        if nums[mid] > nums[right]:
            left = mid + 1
        else:
            right = mid

    # After the loop, left points to the smallest element (the pivot),
    # so the max is the element before it (taking care of wrap-around)
    return nums[left - 1]


