import re

def capital_words_spaces(text: str) -> str:
    # Insert a space between a lowercase or non-letter character and a capital letter,
    # but only when the capital letter starts a new capitalized word.
    # We do this by looking for positions where a capital letter is immediately preceded by
    # a lowercase letter or digit or another capital letter (to handle sequences like "HelloWorld").
    # To avoid inserting spaces inside acronyms or all-caps words, we only insert spaces when
    # the capital letter is followed by lowercase letters.

    # Pattern explanation:
    # (?<=[a-z])(?=[A-Z])  -> position between a lowercase and uppercase letter
    # | (?<=[A-Z])(?=[A-Z][a-z]) -> position between capital letters where the second capital letter starts a capitalized word (followed by lowercase)
    #
    # This handles "HelloWorld" -> "Hello World" and "NASAResearch" -> "NASA Research" but not "NASA" alone.

    pattern = r'(?<=[a-z])(?=[A-Z])|(?<=[A-Z])(?=[A-Z][a-z])'
    return re.sub(pattern, ' ', text)


