def sum_column(data, col_index):
    total = 0
    found_valid_index = False
    for row in data:
        if col_index < len(row):
            found_valid_index = True
            value = row[col_index]
            if isinstance(value, (int, float)):
                total += value
    if not found_valid_index:
        raise IndexError("Column index is invalid for all rows")
    return total


