def substract_elements(data):
    if isinstance(data, (int, float)):
        return data
    if isinstance(data, (list, tuple)):
        if not data:
            return type(data)()
        first = substract_elements(data[0])
        rest = [substract_elements(x) for x in data[1:]]
        # Substract element-wise
        def substract(a, b):
            if isinstance(a, (int, float)) and isinstance(b, (int, float)):
                return a - b
            if isinstance(a, (list, tuple)) and isinstance(b, (list, tuple)):
                return type(a)(substract(x, y) for x, y in zip(a, b))
            # If shapes differ or types differ, treat missing elements as 0
            if isinstance(a, (int, float)) and isinstance(b, (list, tuple)):
                return type(b)(substract(a, y) for y in b)
            if isinstance(a, (list, tuple)) and isinstance(b, (int, float)):
                return type(a)(substract(x, b) for x in a)
            raise TypeError("Unsupported types for subtraction")

        result = first
        for r in rest:
            result = substract(result, r)
        return result
    raise TypeError("Input must be int, float, list or tuple")


