def lucky_num(n):
    # Generate lucky numbers using the sieve of lucky numbers
    # Start with odd numbers from 1 upwards
    lucky_numbers = list(range(1, 2 * n * 10, 2))  # overshoot to ensure enough numbers

    idx = 1  # start from second element (index 1)
    while idx < len(lucky_numbers):
        step = lucky_numbers[idx]
        if step > len(lucky_numbers):
            break
        # Remove every step-th element from the list (1-based indexing)
        # Except the element at position step itself
        # We remove indexes: step-1, 2*step-1, 3*step-1, ... zero-based indexes
        lucky_numbers = [x for i, x in enumerate(lucky_numbers) if (i + 1) % step != 0]
        idx += 1
        if len(lucky_numbers) >= n:
            break
    return lucky_numbers[:n]


