def compute_Last_Digit(a: int, b: int) -> int:
    if a == b:
        return 1
    # Ensure a < b for product calculation
    if a > b:
        a, b = b, a
    length = b - a
    if length >= 5:
        # product includes at least one multiple of 5 and at least one even number => last digit 0
        return 0
    product = 1
    for x in range(a + 1, b + 1):
        product *= x
    return product % 10


