def dif_Square(n: int) -> bool:
    # A number n can be expressed as difference of two squares a^2 - b^2 = n
    # if and only if n is not congruent to 2 mod 4.
    # This is a well-known number theory result:
    # n = a^2 - b^2 = (a-b)(a+b)
    # For n ≡ 2 (mod 4), no such integers a,b exist.
    return n % 4 != 2


