def next_smallest_palindrome(n: int) -> int:
    s = str(n)
    length = len(s)

    # Helper to check if all digits are 9
    if all(ch == '9' for ch in s):
        # Next palindrome greater than n for all 9's is 10..01 (length+1 digits)
        return int('1' + ('0' * (length - 1)) + '1')

    def make_palindrome(left: str, odd_length: bool) -> int:
        if odd_length:
            return int(left + left[:-1][::-1])
        else:
            return int(left + left[::-1])

    odd_length = (length % 2 != 0)
    mid = length // 2

    # Get the left half (and middle if odd)
    if odd_length:
        left = s[:mid+1]
    else:
        left = s[:mid]

    # Form a palindrome from the left half
    palindrome = make_palindrome(left, odd_length)

    if palindrome > n:
        return palindrome

    # If palindrome <= n, increment the left half (including middle if odd) and form palindrome again
    left_num = int(left)
    left_num += 1
    left_str = str(left_num)

    # If increment causes length increase (e.g. 999 -> 1000), adjust
    if len(left_str) > len(left):
        # For example: 999 -> left=999, odd_length=True, increment left_num=1000 (length+1)
        # The next palindrome will be 10..01 with length+1 digits
        return int('1' + ('0' * (length - 1)) + '1')

    return make_palindrome(left_str, odd_length)


