def find_solution(a, b, n):
    # We want to find non-negative integers x,y such that a*x + b*y = n.
    # If none exist, return None.

    # Handle trivial cases
    if n < 0:
        return None
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else None
    if a == 0:
        if n % b == 0 and n // b >= 0:
            return (0, n // b)
        else:
            return None
    if b == 0:
        if n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            return None

    # Use extended Euclidean algorithm to find one integer solution
    def extended_gcd(x, y):
        if y == 0:
            return (x, 1, 0)
        else:
            g, s, t = extended_gcd(y, x % y)
            return (g, t, s - (x // y) * t)

    g, s, t = extended_gcd(a, b)
    if n % g != 0:
        return None  # no integer solutions at all

    # Scale the particular solution
    s *= n // g
    t *= n // g

    # General solution:
    # x = s + k*(b/g)
    # y = t - k*(a/g)
    # We want non-negative x,y.
    # Find k such that x,y >= 0.

    a_div = a // g
    b_div = b // g

    # x >= 0 => s + k*b_div >= 0  => k >= -s / b_div
    # y >= 0 => t - k*a_div >= 0  => k <= t / a_div

    # Since b_div and a_div are integers > 0 if a,b > 0 or < 0 otherwise,
    # we carefully find the interval for k.

    # Note: a and b can be negative or positive. The signs matter.
    # To avoid confusion, let's normalize signs for b_div and a_div:

    # We'll consider the inequalities carefully.

    # Inequality 1: k >= ceil(-s / b_div) if b_div > 0 else floor(-s / b_div)
    # Inequality 2: k <= floor(t / a_div) if a_div > 0 else ceil(t / a_div)

    # Define helper to do division rounding toward +inf or -inf depending on sign

    from math import ceil, floor

    def div_ceil(x, y):
        # returns ceil(x/y)
        return -((-x) // y) if y > 0 else -((-x) // y)

    def div_floor(x, y):
        # returns floor(x/y)
        return x // y

    # Because // in Python floors toward -inf

    # But let's handle the cases explicitly:

    if b_div > 0:
        k_min = ceil(-s / b_div)
    elif b_div < 0:
        k_min = floor(-s / b_div)
    else:
        # b_div == 0 means b==0 handled above, so no solution here
        return None

    if a_div > 0:
        k_max = floor(t / a_div)
    elif a_div < 0:
        k_max = ceil(t / a_div)
    else:
        # a_div == 0 means a==0 handled above
        return None

    # Check if there's an integer k in [k_min, k_max]
    # If k_min > k_max no solution

    if k_min > k_max:
        return None

    # If multiple solutions, pick k that minimizes x+y to return a "nice" solution
    # x = s + k*b_div
    # y = t - k*a_div
    # x+y = s + t + k*(b_div - a_div)

    # If b_div - a_div == 0, all have same x+y, pick k_min
    # else pick k_min or k_max depending on sign of b_div - a_div

    if (b_div - a_div) > 0:
        k = k_min
    elif (b_div - a_div) < 0:
        k = k_max
    else:
        k = k_min

    x = s + k * b_div
    y = t - k * a_div

    if x < 0 or y < 0:
        return None
    return (x, y)


