def get_total_number_of_sequences(n, k):
    # dp[i][x]: number of sequences of length i ending with element x (1-based)
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    # Base case: sequences of length 1
    for x in range(1, k + 1):
        dp[1][x] = 1

    for i in range(2, n + 1):
        for x in range(1, k + 1):
            total = 0
            for y in range(1, k + 1):
                # Check doubling rule:
                # The next element can be either twice or half of the current element
                # Because "the original doubling rule between consecutive elements"
                # means next element is either double or half of previous element
                # So for dp[i][x], the previous element y must be either x*2 or x//2 (if exactly half)
                # Actually, from the previous element y to current x:
                # x == 2*y or y == 2*x
                if x == 2 * y or y == 2 * x:
                    total += dp[i - 1][y]
            dp[i][x] = total

    return sum(dp[n][1:])


