def smallest_missing(arr, low, high):
    """
    Find the smallest non-negative integer missing from arr[low:high+1], 
    assuming arr is sorted with distinct non-negative integers.
    If all integers from 0 to high - low are present in arr[low:high+1], 
    return high + 1.
    """
    left, right = low, high
    while left <= right:
        mid = (left + right) // 2
        expected = mid - low
        if arr[mid] == expected:
            left = mid + 1
        else:
            right = mid - 1
    return left - low


