import re

def text_match(s):
    # Pattern explanation:
    # a followed by zero or more b's: ab*
    # but only match if no b follows: negative lookahead (?!b)
    # meaning directly after the matched substring there's no 'b'
    pattern = r'a b* (?!b)'
    # Remove spaces for correct regex syntax
    pattern = pattern.replace(" ", "")
    match = re.search(pattern, s)
    return "Match" if match else "No match"


