def lucky_num(n):
    numbers = list(range(1, 2 * n * 10, 2))  # start with odd numbers, large enough range
    idx = 1
    while len(numbers) > n:
        step = numbers[idx]
        if step > len(numbers):
            break
        del numbers[step - 1::step]
        idx += 1
    return numbers[:n]


