def compute_Last_Digit(a: int, b: int) -> int:
    if a > b:
        return 0
    # factorial(b)/factorial(a) = product of integers from a+1 to b
    # We want the last digit of this product.
    # If product contains a multiple of 10, last digit is 0.
    # Check if any number in (a+1..b) is multiple of 10
    for x in range(a + 1, b + 1):
        if x % 10 == 0:
            return 0
    last_digit = 1
    for x in range(a + 1, b + 1):
        last_digit = (last_digit * (x % 10)) % 10
    return last_digit


