def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    # Helper to check if all digits are 9
    if all(ch == '9' for ch in s):
        # Next palindrome is 10...01 with length+1 digits
        return int('1' + ('0' * (length - 1)) + '1')

    # Increment num by 1 because we want strictly greater palindrome
    num += 1
    s = str(num)
    length = len(s)

    while True:
        s = str(num)
        if s == s[::-1]:
            return num
        num += 1


