def find_solution(a: int, b: int, n: int):
    # We want to find non-negative integers x, y such that a*x + b*y = n.
    # If no such solution exists, return "No solution".
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else "No solution"
    if a == 0:
        if n % b == 0 and n // b >= 0:
            return (0, n // b)
        else:
            return "No solution"
    if b == 0:
        if n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            return "No solution"

    # To find x, y >= 0 such that a*x + b*y = n,
    # we can try y from 0 up to n//b and check if (n - b*y) divisible by a and non-negative.
    for y in range(n // b + 1):
        remainder = n - b * y
        if remainder < 0:
            break
        if remainder % a == 0:
            x = remainder // a
            if x >= 0:
                return (x, y)
    return "No solution"


