def next_power_of_2(n: int) -> int:
    if n <= 1:
        return 1
    # For positive n > 1, find the smallest power of 2 >= n
    # A standard approach uses bit manipulations:
    # For example, shift bits to fill all bits below the highest set bit,
    # then add 1 to get next power of two if n is not already a power of two.
    # Handle the case when n is already a power of two.

    # If n is already a power of two, return n
    if (n & (n - 1)) == 0:
        return n

    power = 1
    while power < n:
        power <<= 1
    return power


