def find_Max(nums):
    if not nums:
        return None
    left, right = 0, len(nums) - 1
    # If array is not rotated (sorted ascending)
    if nums[left] < nums[right]:
        return nums[right]

    while left < right:
        mid = (left + right) // 2
        # If mid element is greater than next element, mid is max
        if mid < len(nums) - 1 and nums[mid] > nums[mid + 1]:
            return nums[mid]
        # If mid element is smaller than previous element, previous is max
        if mid > 0 and nums[mid] < nums[mid - 1]:
            return nums[mid - 1]

        # Decide which side to go
        if nums[mid] >= nums[left]:
            left = mid + 1
        else:
            right = mid - 1
    return nums[left]


