def str_to_tuple(s: str) -> tuple:
    s = s.strip()
    if not s:
        return ()
    # Determine delimiter: comma or space
    if ',' in s:
        parts = [part.strip() for part in s.split(',')]
    else:
        parts = s.split()
    # Convert each part to int
    return tuple(int(part) for part in parts)


