def lucky_num(n):
    numbers = list(range(1, 2 * n * 10))  # Start with a large enough list to find n lucky numbers
    idx = 1  # Start from the second position (index 1), since indexing is zero-based

    while idx < len(numbers) and len(numbers) < n * 10:
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th number starting from step-1 index
        del numbers[step - 1::step]
        idx += 1

    return numbers[:n]


