from functools import lru_cache

def get_total_number_of_sequences(m: int, n: int) -> int:
    @lru_cache(None)
    def count_sequences(pos: int, prev: int) -> int:
        if pos == n:
            return 1
        total = 0
        start = max(prev, 1) if pos > 0 else 1
        # next element must be >= prev and >= 2*prev to satisfy condition "each element is at least twice the previous one"
        # Since the sequence is nondecreasing and each element >= 2*prev,
        # effectively next element >= max(prev, 2*prev) = 2*prev (since 2*prev >= prev)
        # For pos=0 (first element), no previous element, so can pick from 1 to m
        min_next = 1 if pos == 0 else 2*prev
        for val in range(min_next, m+1):
            total += count_sequences(pos+1, val)
        return total

    return count_sequences(0, 0)


