def remove_column(data, index):
    if isinstance(data, dict):
        return {k: remove_column(v, index) for k, v in data.items()}
    if isinstance(data, list):
        new_list = []
        for item in data:
            if isinstance(item, list):
                # Remove element at index if possible
                if 0 <= index < len(item):
                    new_item = item[:index] + item[index+1:]
                else:
                    new_item = item[:]
                new_list.append(remove_column(new_item, index))
            else:
                new_list.append(remove_column(item, index))
        return new_list
    return data


