def smallest_missing(arr):
    # arr is a sorted list of integers starting from 0
    # find the smallest missing non-negative integer
    left, right = 0, len(arr)
    while left < right:
        mid = (left + right) // 2
        if arr[mid] == mid:
            left = mid + 1
        else:
            right = mid
    return left


