def find_Max(arr, start, end):
    if start == end:
        return arr[start]
    mid = (start + end) // 2
    left_max = find_Max(arr, start, mid)
    right_max = find_Max(arr, mid + 1, end)
    return left_max if left_max > right_max else right_max


