def lucky_num(n):
    nums = list(range(1, 2 * n * 10))  # large enough initial list to get at least n lucky numbers
    idx = 1  # start removing every nums[idx]-th number, with idx=1 means every 2nd
    while idx < len(nums):
        step = nums[idx]
        if step > len(nums):
            break
        # Remove every step-th number starting from index step-1 (0-based)
        nums = [num for i, num in enumerate(nums) if (i + 1) % step != 0]
        idx += 1
        if len(nums) >= n:
            continue
        else:
            # If the list shrank too much, extend it
            # This rarely happens with the initial large list, but just in case
            needed = (n - len(nums)) * 10
            start = nums[-1] + 1
            nums.extend(range(start, start + needed))
    return nums[:n]


