def compute_Last_Digit(a: int, b: int) -> int:
    # Compute the last non-zero digit of factorial(b)/factorial(a)
    # which is the product (a+1)*(a+2)*...*b without trailing zeros.
    # Approach:
    # - Count factors of 5 and 2 in the product to determine trailing zeros.
    # - Remove corresponding factors of 10 from product.
    # - Multiply remaining factors modulo 10 (tracking last non-zero digit).

    def count_factor(n, factor):
        count = 0
        while n % factor == 0:
            n //= factor
            count += 1
        return count

    product = 1
    total_5 = 0
    total_2 = 0

    for x in range(a+1, b+1):
        # Count factors of 5 and 2 for each x
        c5 = count_factor(x, 5)
        c2 = count_factor(x, 2)
        total_5 += c5
        total_2 += c2

        # Remove all 2s and 5s from x to prevent trailing zeros in multiplication
        val = x
        for _ in range(c5):
            val //= 5
        for _ in range(c2):
            val //= 2
        product = (product * val) % 10

    # Balance leftover 2s (since each 5 matched with a 2 to make 10)
    leftover_2 = total_2 - total_5
    for _ in range(leftover_2):
        product = (product * 2) % 10

    return product


