def dif_Square(n: int) -> bool:
    # A number n can be represented as a difference of two squares:
    # n = a^2 - b^2 = (a+b)(a-b)
    # So n = x * y where x = a+b, y = a-b and both x and y have the same parity
    # (both odd or both even), and x > y > 0.
    # For n > 0, check if there exist integers x, y with the same parity, x > y > 0, and x*y = n.
    # For n = 0, 0 = 0^2 - 0^2, so True.
    # For n < 0, difference of squares can be negative as well (e.g. 3^2 - 4^2 = -7).
    # So check for absolute value and consider sign accordingly.

    # Handle zero quickly
    if n == 0:
        return True

    abs_n = abs(n)

    # Iterate over divisors y of abs_n
    # For each divisor y, x = abs_n // y
    # Check if x and y have same parity and (x + y) % 2 == 0 and (x - y) % 2 == 0
    # Then a = (x + y)//2, b = (x - y)//2 are integers.
    # Also, a^2 - b^2 = n or -n, so for negative n, swap a and b to get negative.

    from math import isqrt

    for y in range(1, isqrt(abs_n) + 1):
        if abs_n % y == 0:
            x = abs_n // y
            if (x + y) % 2 == 0 and (x - y) % 2 == 0:
                # Construct a,b
                a = (x + y) // 2
                b = (x - y) // 2
                # Check if a^2 - b^2 == n
                if a*a - b*b == n:
                    return True
                # For negative n, also check b^2 - a^2 == n
                if b*b - a*a == n:
                    return True
    return False


