from typing import List, Optional

def Find_Min_Length(groups: List[List[float]]) -> Optional[float]:
    if not groups:
        return None
    if len(groups) == 1:
        if not groups[0]:
            return None
        return min(groups[0])
    min_value = None
    for group in groups:
        if group:
            group_min = min(group)
            if min_value is None or group_min < min_value:
                min_value = group_min
    return min_value


