from collections.abc import Sequence

def sort_sublists(collection):
    def sort_subseq(subseq):
        # Check if subseq is a sequence (but not string)
        if not isinstance(subseq, Sequence) or isinstance(subseq, str):
            return subseq
        # If subseq is empty, return as is
        if len(subseq) == 0:
            return subseq
        # Check if items inside subseq are sequences with at least one element
        # If so, sort by first element of each item
        # Otherwise, sort the subseq itself (the items directly)
        first_item = subseq[0]
        if isinstance(first_item, Sequence) and not isinstance(first_item, str) and len(first_item) > 0:
            try:
                return type(subseq)(sorted(subseq, key=lambda x: x[0]))
            except Exception:
                # fallback: return as is if error
                return subseq
        else:
            # subseq items are not sequences, sort subseq elements directly
            try:
                return type(subseq)(sorted(subseq))
            except Exception:
                return subseq

    # For dict: sort each value if it is a subsequence
    if isinstance(collection, dict):
        return type(collection)((k, sort_subseq(v)) for k, v in collection.items())

    # For sequences (list, tuple, etc.) but not strings
    if isinstance(collection, Sequence) and not isinstance(collection, str):
        return type(collection)(sort_subseq(subseq) for subseq in collection)

    # Otherwise, return as is
    return collection


