def find_solution(a, b, n):
    if b == 0:
        # Then equation is ax = n, so check if n is divisible by a and solution non-negative
        if a != 0 and n % a == 0 and n // a >= 0:
            return (n // a, 0)
        return None

    x = 0
    while True:
        remainder = n - a * x
        if remainder < 0:
            # Since x is increasing and a*x grows, no further solutions possible
            return None
        if remainder % b == 0:
            y = remainder // b
            if y >= 0:
                return (x, y)
        x += 1


