def get_total_number_of_sequences(n: int, k: int) -> int:
    from functools import lru_cache

    @lru_cache(None)
    def count_sequences(prev: int, length: int) -> int:
        if length == k:
            return 1
        total = 0
        start = prev * 2
        if start > n:
            return 0
        for next_val in range(start, n + 1):
            total += count_sequences(next_val, length + 1)
        return total

    total_sequences = 0
    for start_val in range(1, n + 1):
        total_sequences += count_sequences(start_val, 1)
    return total_sequences


