def str_to_tuple(s: str, from_sep: str = None, to_sep: str = ",") -> str:
    """
    Convert a string of grouped numbers from one separator format to another.

    Parameters:
    - s: input string containing grouped numbers
    - from_sep: separator used in the input string; if None, auto-detect from comma or space
    - to_sep: separator to use in the output string (default comma)

    Returns:
    - reformatted string with numbers separated by to_sep
    """
    # Auto-detect separator if not given
    if from_sep is None:
        if "," in s:
            from_sep = ","
        elif " " in s:
            from_sep = " "
        else:
            # No separator found, assume single number string
            return s.strip()

    parts = [p.strip() for p in s.split(from_sep)]
    # Remove empty parts resulting from consecutive separators
    parts = [p for p in parts if p]

    return to_sep.join(parts)


