from typing import Any, Iterable, Mapping, Optional

def sum_column(data: Iterable[Mapping[str, Any]], group_key: str, select_group: Any, sum_key: str) -> float:
    """
    Sum values from the 'sum_key' column for entries in 'data' where the 'group_key' equals 'select_group'.

    Parameters:
    - data: iterable of dict-like objects representing grouped data.
    - group_key: the key to group/filter by.
    - select_group: the value of the group_key to select.
    - sum_key: the key corresponding to the values to sum.

    Returns:
    - The sum of all values under sum_key for selected group entries, as float.
      Non-numeric or missing values are treated as zero.
    """
    total = 0.0
    for row in data:
        if row.get(group_key) == select_group:
            val = row.get(sum_key, 0)
            try:
                total += float(val)
            except (TypeError, ValueError):
                # ignore non-convertible values, treat as zero
                pass
    return total


