def substract_elements(groups):
    """
    Given a list of groups (each a list of numbers), remove pairs of identical numbers from each group individually.
    Return a list of groups with only the leftover elements (unpaired) in each.
    For example:
    substract_elements([[1,1,2,3,3,3]]) returns [[2,3]]
    substract_elements([[]]) returns [[]]
    """
    result = []
    for group in groups:
        counts = {}
        for num in group:
            counts[num] = counts.get(num, 0) + 1
        leftovers = []
        for num, count in counts.items():
            if count % 2 == 1:
                leftovers.append(num)
        result.append(leftovers)
    return result


