def lucky_num(n):
    # Start with a large enough list of odd numbers (lucky numbers are always odd after the first step)
    numbers = list(range(1, 3 * n * n, 2))
    idx = 1  # start from the second element (1-based position 2)
    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th element, counting from 1-based indexing
        # So remove elements at positions step-1, 2*step-1, 3*step-1, ...
        numbers = [num for i, num in enumerate(numbers) if (i + 1) % step != 0]
        idx += 1
        if len(numbers) >= n:
            continue
        if len(numbers) < idx:
            break
    return numbers[:n]


