def compute_Last_Digit(a, b):
    # We want the last digit of (b! // a!) = (a+1)*(a+2)*...*b
    # If b == a, the result is 1, last digit is 1
    if b == a:
        return 1
    # If the product includes a multiple of 10, last digit is 0
    # Check if any number in (a+1 to b) is divisible by 10
    for x in range(a + 1, b + 1):
        if x % 10 == 0:
            return 0
    # Otherwise, compute the product modulo 10 to get last digit
    last_digit = 1
    for x in range(a + 1, b + 1):
        last_digit = (last_digit * (x % 10)) % 10
    return last_digit


