def next_smallest_palindrome(n: int) -> int:
    # Handle edge cases
    if n <= 0:
        # No palindrome smaller than non-positive numbers in positive integers
        return -1
    if n <= 10:
        # For single-digit numbers > 0, the next smallest palindrome is n-1
        return n - 1

    s = str(n)
    length = len(s)

    # Decrement n by 1 because we want strictly smaller palindrome
    n -= 1
    s = str(n)
    length = len(s)

    def is_palindrome(x: str) -> bool:
        return x == x[::-1]

    # If length is 1, just return n itself (already handled above)
    # For longer numbers, try to build palindromes smaller than n

    while True:
        s = str(n)
        if is_palindrome(s):
            return n
        n -= 1
        if n < 0:
            return -1


