def get_total_number_of_sequences(n: int, m: int) -> int:
    # dp[i][x] = number of sequences of length i ending with element x
    # i ranges from 1 to n, x ranges from 1 to m
    if n == 1:
        return m  # any element from 1 to m can start the sequence

    dp = [0] * (m + 1)
    # Base case: sequences of length 1, count = 1 for each x in [1..m]
    for x in range(1, m + 1):
        dp[x] = 1

    for length in range(2, n + 1):
        new_dp = [0] * (m + 1)
        # prefix sums for dp to quickly get sums over ranges
        prefix = [0] * (m + 2)
        for x in range(1, m + 1):
            prefix[x] = prefix[x - 1] + dp[x]

        for x in range(1, m + 1):
            # next element y must satisfy:
            # y >= 2*x and y <= m
            start = 2 * x
            if start > m:
                continue
            # sum dp[y] for y in [start..m]
            # but we want dp of previous length ending at y, so here we invert:
            # Actually, we want sequences ending at current length = i with element x,
            # so for dp of length i-1, elements y where x >= 2*y ?
            # Wait, we must be careful:

            # The problem states:
            # each next element >= 2 * previous element and <= m

            # So if previous element is p, next element n satisfies:
            # n >= 2*p and n <= m

            # In dp, dp[length][x] = sum over dp[length-1][p] where x >= 2*p and x <= m

            # So for fixed x at current length, previous p must satisfy:
            # p <= x / 2
            # and p in [1..m]

            max_p = x // 2
            if max_p < 1:
                continue
            new_dp[x] = prefix[max_p]

        dp = new_dp

    return sum(dp[1:])


