def substract_elements(t):
    if isinstance(t, tuple):
        if not t:
            return ()
        first = t[0]
        if isinstance(first, tuple):
            # recursively process each element
            return tuple(substract_elements(e) for e in t)
        else:
            # t is a flat tuple of numbers; subtract elements left to right
            result = first
            for num in t[1:]:
                result -= num
            return result
    else:
        # if input is a number, just return it
        return t


