def circular_shift(x, shift):
    s = str(x)
    n = len(s)
    if abs(shift) > n:
        return s[::-1]
    shift %= n
    if shift == 0:
        return s
    # positive shift: left circular shift
    # negative shift: right circular shift
    if shift > 0:
        return s[shift:] + s[:shift]
    else:
        shift = -shift
        return s[-shift:] + s[:-shift]


