def anti_shuffle(s):
    import re
    # Split input into words and spaces, preserving all spaces
    parts = re.split(r'(\s+)', s)
    result = []
    for part in parts:
        if part.isspace() or part == '':
            # preserve spaces as is
            result.append(part)
        else:
            # reorder characters in the word ascending by ascii
            ordered = ''.join(sorted(part))
            result.append(ordered)
    return ''.join(result)


