def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)

    def is_non_decreasing(a):
        return all(a[i] <= a[i+1] for i in range(len(a)-1))

    # Check all rotations for non-decreasing order
    for shift in range(n):
        rotated = arr[-shift:] + arr[:-shift]
        if is_non_decreasing(rotated):
            return True
    return False


