from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    def max_depth(group: str) -> int:
        # Compute max depth by scanning characters and tracking current depth
        # without using loops or recursion by using map and accumulate
        from itertools import accumulate

        # Map '(' to +1, ')' to -1
        changes = list(map(lambda c: 1 if c == '(' else -1, group))
        depths = list(accumulate(changes))
        return max(depths) if depths else 0

    return list(map(max_depth, paren_string.split()))


