from typing import List, Tuple

def parse_music(music_string: str) -> Tuple[List[int], str]:
    # Map notes to beats using dictionary
    beats_map = {'o': 4, 'o|': 2, '.|': 1}

    # Split input string by spaces
    notes = music_string.split()

    # Convert notes to beats list without loops:
    beats_list = list(map(beats_map.get, notes))

    # If no notes, return empty list and empty string (fix for parse_music(''))
    if not notes:
        return ([], '')

    # Extract base notes (first character of each note)
    base_notes = list(map(lambda n: n[0], notes))

    # Count occurrences of base notes (only 'o' and '.' possible)
    count_o = base_notes.count('o')
    count_dot = base_notes.count('.')

    # Beats per base note:
    beats_per_note = {'o': 4, '.': 1}

    # Determine most common note (tie-break by longer beat)
    if count_o > count_dot:
        most_common = 'o'
    elif count_dot > count_o:
        most_common = '.'
    else:  # tie
        most_common = 'o' if beats_per_note['o'] >= beats_per_note['.'] else '.'

    return (beats_list, most_common)


