from typing import List, Any, Tuple

def filter_integers(values: List[Any], format: str) -> Tuple[List[int], str]:
    # Convert input to list if it is a string (treat each character as an element)
    vals = list(values) if isinstance(values, str) else values

    # Use list comprehension (not a loop statement) to separate integers and non-integers
    ints = [v for v in vals if isinstance(v, int)]
    non_ints = [v for v in vals if not isinstance(v, int)]

    # Format non-integers string according to 'format'
    if format == "string":
        # Join their string representation with spaces
        non_ints_str = " ".join(str(x) for x in non_ints)
    else:
        # 'integer' format means join their default str representation (same as above)
        non_ints_str = " ".join(str(x) for x in non_ints)

    return ints, non_ints_str


