def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)

    # Helper to check if array is sorted non-decreasing
    def is_sorted(a):
        return all(a[i] <= a[i+1] for i in range(len(a)-1))

    # Since loops are disallowed for the operation, but allowed in logic,
    # we just find if the array can be rotated to sorted form.

    # The array is guaranteed unique elements.
    # The array can be sorted by right shifts if and only if
    # it is a rotation of a sorted array.

    # Find the index where the order breaks (the "pivot")
    breaks = [i for i in range(n-1) if arr[i] > arr[i+1]]

    if len(breaks) == 0:
        # Already sorted
        return True
    if len(breaks) > 1:
        # More than one break means cannot be rotated into sorted array
        return False

    # Only one break point
    pivot = breaks[0]

    # Check if rotating right by n - (pivot+1) positions sorts the array
    # Rotate arr to the right (n - (pivot+1)) times:
    shift = n - (pivot + 1)
    rotated = arr[-shift:] + arr[:-shift]

    return is_sorted(rotated)


