def maximum(arr, k):
    if k == 0:
        return []
    # Find the k largest elements without using built-in sort.
    # Since we cannot use built-in sort and time complexity O(1) is impossible for sorting,
    # we assume O(k * n) or similar is acceptable.
    # We implement a selection of k largest elements by repeated max selection.

    # Copy arr to avoid modifying original
    arr_copy = arr[:]
    result = []

    for _ in range(k):
        # Find max element in arr_copy
        max_val = arr_copy[0]
        for val in arr_copy[1:]:
            if val > max_val:
                max_val = val
        result.append(max_val)
        arr_copy.remove(max_val)

    # Now we have k largest elements in result but unsorted
    # We need to sort them in ascending order without built-in sort
    # Use simple insertion sort since k <= len(arr) <= 1000 (small)
    for i in range(1, k):
        key = result[i]
        j = i - 1
        while j >= 0 and result[j] > key:
            result[j + 1] = result[j]
            j -= 1
        result[j + 1] = key

    return result


