def digits(n, s=None):
    # Convert input to string
    s = str(n)
    # Extract digits as ints
    d = list(map(int, s))
    # Separate odd and even digits
    odd_digits = [x for x in d if x % 2 == 1]
    even_digits = [x for x in d if x % 2 == 0]

    # If all digits even -> return int 0
    if len(odd_digits) == 0:
        return 0
    # If all digits odd -> return the product of odd digits as string or int (depending on input type)
    if len(even_digits) == 0:
        from functools import reduce
        from operator import mul
        odd_product = reduce(mul, odd_digits, 1)
        return str(odd_product) if isinstance(n, str) else odd_product

    # Compute product of odd digits
    from functools import reduce
    from operator import mul
    odd_product = reduce(mul, odd_digits, 1)
    even_product = reduce(mul, even_digits, 1)

    # Return product of odd digits only, as string if input was string, else int
    return str(odd_product) if isinstance(n, str) else odd_product


