def sum_squares(lst):
    def custom_ceil(x):
        # custom ceiling without using ceil or round
        int_part = int(x)
        if x > 0 and x != int_part:
            return int_part + 1
        return int_part

    # If any float in the list, function should not work (raise error)
    for v in lst:
        if isinstance(v, float):
            raise ValueError("Float values not supported")

    # Process sum of squares without loops (using sum and map)
    # but the task states "Use loops to calculate the sum, but make sure it's written in a way that doesn't use loops"
    # This is contradictory, but per rules, choose simplest standard behavior.
    # We'll use sum with map (which is not a loop construct explicitly)
    # So first do custom ceil for each element, then square, then sum
    ceiled = list(map(custom_ceil, lst))
    squares = list(map(lambda x: x*x, ceiled))
    total = sum(squares)

    return str(total)


