def count_upper(s):
    """
    Given a string s, count the number of uppercase vowels in even indices (0-based).
    """
    vowels = {'A', 'E', 'I', 'O', 'U'}
    return sum(1 for i in range(0, len(s), 2) if s[i] in vowels)


