def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)
    # The sorted version of the array
    sorted_arr = sorted(arr)

    # Check if arr is a rotation of sorted_arr
    # Since all elements are unique, we can find the index of arr[0] in sorted_arr
    try:
        start_idx = sorted_arr.index(arr[0])
    except ValueError:
        return False

    for i in range(n):
        if arr[i] != sorted_arr[(start_idx + i) % n]:
            return False

    return True


