def monotonic(seq):
    if not seq:
        return True
    non_decreasing = all(x <= y for x, y in zip(seq, seq[1:]))
    non_increasing = all(x >= y for x, y in zip(seq, seq[1:]))
    return non_decreasing or non_increasing


