def move_one_ball(seq):
    if not seq:
        return True
    n = len(seq)
    # Since values are distinct, sorted means strictly increasing
    sorted_seq = sorted(seq)
    # Check all rightward rotations of seq:
    # Rotation by k means the last k elements come to front
    for k in range(n):
        rotated = seq[-k:] + seq[:-k]
        if rotated == sorted_seq:
            return True
    return False


