from typing import List

def parse_music(music_string: str) -> List[int]:
    """
    Parses a string of musical notes represented in a special ASCII format,
    returning a list of integers corresponding to the duration (in beats) of each note.

    Since the exact format and beat counting are unspecified, we use a standard,
    least-surprising approach:

    - Each note is represented by a single uppercase letter A-G.
    - Each note has a base duration of 1 beat.
    - Each consecutive '-' character following the note adds 1 beat to its duration.
    - Notes are parsed in order.

    For example:
    "C-D--E" -> [1, 2, 3]
    "A--B-C-" -> [3, 1, 2]

    Notes and dashes are contiguous; no other characters are considered part of a note.
    """
    beats = []
    i = 0
    n = len(music_string)
    while i < n:
        c = music_string[i]
        if c in "ABCDEFG":
            duration = 1
            i += 1
            # Count subsequent dashes adding beats
            while i < n and music_string[i] == '-':
                duration += 1
                i += 1
            beats.append(duration)
        else:
            # Skip any characters not recognized as notes or dashes (to be robust)
            i += 1
    return beats


