def anti_shuffle(s):
    result = []
    i = 0
    while i < len(s):
        if s[i] == ' ':
            result.append(' ')
            i += 1
        else:
            start = i
            while i < len(s) and s[i] != ' ':
                i += 1
            word = s[start:i]
            sorted_word = ''.join(sorted(word))
            result.append(sorted_word)
    return ''.join(result)


