def order_by_points(nums):
    def digit_sum(n):
        s = str(n)
        if s[0] == '-':
            # first digit after '-' is negative
            total = -int(s[1])
            # rest digits are positive
            for ch in s[2:]:
                total += int(ch)
            return total
        else:
            return sum(int(ch) for ch in s)
    return sorted(nums, key=lambda x: digit_sum(x))


