def move_one_ball(arr):
    if not arr:
        return True
    n = len(arr)
    # Count how many "drops" (strict decreases) are in the array
    drops = 0
    for i in range(1, n):
        if arr[i] < arr[i-1]:
            drops += 1
            if drops > 1:
                return False
    # Also check between last and first element to handle rotation wrap
    if arr[0] < arr[-1]:
        # If there's no drop in the middle but arr[0] < arr[-1], this means
        # the array is sorted but not rotated, so it's fine.
        return drops == 0
    # If there is exactly one drop, check if rotating at the drop point sorts the array
    return drops <= 1


