def parse_nested_parens(paren_string):
    max_depth = 0
    current_depth = 0
    stack = []
    for ch in paren_string:
        if ch == '(':
            stack.append(ch)
            current_depth += 1
            if current_depth > max_depth:
                max_depth = current_depth
        elif ch == ')':
            if stack:
                stack.pop()
                current_depth -= 1
            # else: unbalanced closing, ignore
    # At the end, ignore any unbalanced '(' left in stack.
    return max_depth


