def sum_squares(lst):
    """
    This function will take a list. For all entries in the list, the function shall square the entry 
    if its index is a multiple of 3 and will cube the entry if its index is a multiple of 4 and not a multiple of 3. 
    The function will not change the entries in the list whose indexes are not a multiple of 3 or 4. 
    The function shall then return the sum of all entries. 
    """
    total = 0
    for i, val in enumerate(lst):
        if i % 3 == 0:
            total += val ** 2
        elif i % 4 == 0:
            total += val ** 3
        else:
            total += val
    return total


