def parse_music(data: str) -> list[int]:
    # Interpret each symbol in the input string as a note duration,
    # returning a list of integers representing durations.
    # Since the exact mapping is unspecified, the standard simplest interpretation:
    # Map each character to its count as a duration unit.
    # A common standard is to convert note duration symbols to their length in ticks or units.
    #
    # Since no mapping was given, but the answer says symbols represent durations rather than pitches,
    # the simplest standard approach is to parse digits as durations or map note duration symbols.
    #
    # Without further info, the most standard is to interpret characters as durations by their ASCII or a set mapping.
    #
    # To keep it minimal and meaningful, convert each character to its integer value if digit,
    # otherwise assign a fixed duration (e.g. 1).
    #
    # However, since "the meaning of each symbol is common knowledge," and it's about durations,
    # a standard music duration notation is: w=whole(4), h=half(2), q=quarter(1), e=eighth(0.5), s=sixteenth(0.25)
    # We'll map letters w,h,q,e,s to durations in ticks (scaled by 4 to keep integers):
    durations_map = {
        'w': 16,  # whole note = 4 beats * 4 = 16
        'h': 8,   # half note = 2 beats * 4 = 8
        'q': 4,   # quarter note = 1 beat * 4 = 4
        'e': 2,   # eighth note = 0.5 beat * 4 = 2
        's': 1    # sixteenth note = 0.25 beat *4 =1
    }
    result = []
    for c in data:
        if c in durations_map:
            result.append(durations_map[c])
        else:
            # ignore unknown symbols (or could append 0)
            pass
    return result


