def monotonic(nums):
    if not nums:
        return True
    non_decreasing = True
    non_increasing = True
    for i in range(1, len(nums)):
        if nums[i] < nums[i-1]:
            non_decreasing = False
        if nums[i] > nums[i-1]:
            non_increasing = False
        if not non_decreasing and not non_increasing:
            return False
    return True


