def will_it_fly(q, w):
    def describe(obj):
        can_fly = obj.get('can_fly', False)
        ok = obj.get('ok', False)
        weight = obj.get('weight', 0)
        if not ok:
            return "Object is not okay."
        if not can_fly:
            return "Object cannot fly."
        if weight > w:
            return f"Object is too heavy (weight {weight} > limit {w})."
        return "Object can fly."

    # If q is a single object (dict with required keys)
    if isinstance(q, dict):
        return describe(q)

    # If q is a sequence of numbers (weights)
    try:
        weights = list(q)
    except TypeError:
        return "Invalid input."

    # All elements numeric?
    if not all(isinstance(x, (int, float)) for x in weights):
        return "Invalid input."

    total_weight = sum(weights)
    if total_weight > w:
        return f"Total weight is too heavy ({total_weight} > limit {w})."
    else:
        return "All objects can fly within weight limit."


