def max_fill(grid, capacity):
    # Number of wells = number of columns
    if not grid or not grid[0]:
        return 0
    rows = len(grid)
    cols = len(grid[0])

    total_lowerings = 0
    for col in range(cols):
        # Count water units in this well (column)
        water_units = sum(grid[row][col] for row in range(rows))
        # Calculate how many times to lower container for this well
        lowers = (water_units + capacity - 1) // capacity
        total_lowerings += lowers

    return total_lowerings


