def select_words(s, n):
    vowels = set('aeiouAEIOU')
    result = []
    length = len(s)
    if length == 0:
        return result

    for start in range(length):
        count_non_vowels = 0
        for end in range(start, length):
            ch = s[end]
            if ch.isalpha() and ch not in vowels:
                count_non_vowels += 1
            if count_non_vowels == n:
                # include substring s[start:end+1]
                result.append(s[start:end+1])
            elif count_non_vowels > n:
                break
    return result


