def order_by_points(numbers):
    def digit_sum_weight(n):
        s = str(n)
        if s[0] == '-':
            # first digit negative
            first_digit = -int(s[1])
            rest = s[2:]
            rest_sum = sum(int(d) for d in rest) if rest else 0
            return first_digit + rest_sum
        else:
            return sum(int(d) for d in s)
    return sorted(numbers, key=digit_sum_weight)


