from typing import List

def parse_music(music_string: str) -> List[int]:
    tokens = music_string.split()
    durations = []
    for token in tokens:
        if token == 'o':
            durations.append(4)
        elif token == 'o|':
            durations.append(2)
        elif token == '.' or token == '.|':
            durations.append(1)
        else:
            # Unknown token: to be safe, treat as 1 beat (or could raise an error)
            durations.append(1)
    return durations


