def anti_shuffle(s):
    result = []
    i = 0
    n = len(s)
    while i < n:
        if s[i] == ' ':
            # Preserve spaces as is
            result.append(' ')
            i += 1
        else:
            # Extract a word (consecutive non-space characters)
            start = i
            while i < n and s[i] != ' ':
                i += 1
            word = s[start:i]
            # Sort characters by ASCII
            sorted_word = ''.join(sorted(word))
            result.append(sorted_word)
    return ''.join(result)


