def order_by_points(nums):
    def digit_sum(n):
        s = str(abs(n))
        if n >= 0:
            return sum(int(d) for d in s)
        else:
            # For negative numbers: negate the first digit, add the rest as positive
            return -int(s[0]) + sum(int(d) for d in s[1:])
    return sorted(nums, key=digit_sum)


