def parse_nested_parens(paren_string: str) -> List[int]:
    """
    Parses the input string which contains multiple groups of nested parentheses concatenated together 
    (no explicit separators), and returns a list of the maximum nesting depth for each group.

    A "group" is defined as a balanced parentheses substring. The input is assumed to be a concatenation
    of one or more balanced parentheses groups.

    For each group, the function computes the deepest level of nested parentheses.
    """
    depths = []
    current_depth = 0
    max_depth = 0

    for ch in paren_string:
        if ch == '(':
            current_depth += 1
            if current_depth > max_depth:
                max_depth = current_depth
        elif ch == ')':
            current_depth -= 1
            if current_depth == 0:
