def parse_music(music_string: str) -> List[int]:
    notes = music_string.split()
    durations = []
    for note in notes:
        if note == 'o':
            durations.append(4)
        elif note == 'o|':
            durations.append(2)
        elif note == '.|':
            durations.append(1)
        else:
            # If unknown note format, could raise or ignore; here we ignore
            pass
    return durations


