def decode_shift(s: str):
    """
    Takes a string encoded or decoded by shifting every alphabetical character by 3 positions.
    Returns the string with every alphabetical character shifted by 3 positions in the opposite direction,
    preserving case and leaving non-alphabetic characters unchanged.
    """
    def shift_char(ch):
        if 'a' <= ch <= 'z':
            return chr((ord(ch) - ord('a') - 3) % 26 + ord('a'))
        elif 'A' <= ch <= 'Z':
            return chr((ord(ch) - ord('A') - 3) % 26 + ord('A'))
        else:
            return ch

    return "".join(shift_char(ch) for ch in s)


