def anti_shuffle(s):
    import re
    # Split string into words and spaces preserving order
    parts = re.findall(r'\S+|\s+', s)
    result = []
    for part in parts:
        if part.isspace():
            # Keep spaces as is
            result.append(part)
        else:
            # Sort characters in ascending ASCII order
            sorted_word = ''.join(sorted(part))
            result.append(sorted_word)
    return ''.join(result)


