def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)

    def is_sorted_non_decreasing(a):
        return all(a[i] <= a[i+1] for i in range(len(a)-1))

    def is_sorted_non_increasing(a):
        return all(a[i] >= a[i+1] for i in range(len(a)-1))

    # Check all right shifts
    for shift in range(n):
        shifted = arr[-shift:] + arr[:-shift]
        if is_sorted_non_decreasing(shifted) or is_sorted_non_increasing(shifted):
            return True
    return False


