def will_it_fly(q, w):
    if not q:
        return False
    if len(q) == 1:
        return False
    total_weight = sum(q)
    if total_weight > w:
        return False
    mid = len(q) // 2
    if len(q) % 2 == 0:
        left_sum = sum(q[:mid])
        right_sum = sum(q[mid:])
    else:
        left_sum = sum(q[:mid])
        right_sum = sum(q[mid+1:])
    return left_sum == right_sum


